        g.appendChild(svgEl('line', strokeAttrs({ x1: -18, y1: 0, x2: -7, y2: 0 })));
        g.appendChild(svgEl('line', strokeAttrs({ x1: -3, y1: -5, x2: 12, y2: -12 })));
