      g.appendChild(svgEl('line', strokeAttrs({ x1: -18, y1: 0, x2: -9, y2: 0 })));
      g.appendChild(svgEl('line', strokeAttrs({ x1: 9, y1: 0, x2: 18, y2: 0 })));
